-- Generated localized release notes.
local _, namespace = ...
namespace.releaseNotesByLocale = {["deDE"]={["sections"]={{["items"]={"Automatisch eingeblendete Patchnotes erhalten jetzt den Controller-Fokus. Du kannst sie direkt lesen oder mit Zurück schließen.","Beim Scrollen mit dem rechten Stick bewegt sich nun auch der Scrollbalken. Die gespeicherte Leseposition bleibt dabei aktuell.","Beim Wechsel im Verlauf wird die Auswahl sicher versetzt, wenn ein Bedienelement verschwindet oder deaktiviert wird. Nach einem Seitenwechsel wird die Navigation aktualisiert."},["title"]="Patchnotes mit dem Controller"}},["version"]="9.2.0-beta.1",["welcome"]="Dieses kleine Beta-Update verbessert die Bedienung der Patchnotes mit dem Controller."},["esES"]={["sections"]={{["items"]={"Cuando las notas se abren automáticamente tras una actualización, ahora reciben el foco del mando. Puedes cerrarlas directamente con Atrás.","Al desplazarte con el stick derecho, la barra se mueve junto con el texto y la posición de lectura guardada se mantiene al día.","Al navegar por el Historial, la selección pasa a un control válido si el botón seleccionado desaparece o deja de estar disponible. Los controles se actualizan al cambiar de página."},["title"]="Notas del parche con mando"}},["version"]="9.2.0-beta.1",["welcome"]="Esta pequeña actualización de la beta mejora la lectura de las notas del parche con mando."},["esMX"]={["sections"]={{["items"]={"Las notas que aparecen automáticamente después de una actualización ahora reciben el foco del control. Puedes cerrarlas de inmediato con Atrás.","Al usar el stick derecho, la barra de desplazamiento acompaña al texto y se actualiza la posición de lectura guardada.","La navegación del Historial conserva una selección válida cuando un botón se oculta o se desactiva, y actualiza los controles después de cambiar de página."},["title"]="Correcciones en las notas del parche"}},["version"]="9.2.0-beta.1",["welcome"]="Esta actualización de la beta mejora el uso de las notas del parche con control."},["frFR"]={["sections"]={{["items"]={"Les notes qui s’ouvrent automatiquement après une mise à jour prennent désormais le focus de la manette. Vous pouvez les fermer directement avec Retour.","Le défilement au stick droit déplace maintenant la barre de défilement et met à jour la position de lecture mémorisée.","Dans l’Historique, la sélection passe à un élément disponible lorsqu’un bouton disparaît ou devient indisponible. La navigation est actualisée après chaque changement de page."},["title"]="Corrections des notes de mise à jour"}},["version"]="9.2.0-beta.1",["welcome"]="Cette petite mise à jour de la bêta facilite la lecture des notes à la manette."},["itIT"]={["sections"]={{["items"]={"Le note aperte automaticamente dopo un aggiornamento ora ricevono il focus del controller. Puoi quindi chiuderle subito con Indietro.","Lo stick destro ora sposta anche la barra di scorrimento e mantiene aggiornata la posizione di lettura memorizzata.","Nella Cronologia, la selezione passa a un controllo valido quando un pulsante scompare o viene disattivato. La navigazione si aggiorna dopo ogni cambio di pagina."},["title"]="Correzioni alle note della patch"}},["version"]="9.2.0-beta.1",["welcome"]="Questo piccolo aggiornamento della beta migliora la lettura delle note della patch con il controller."},["koKR"]={["sections"]={{["items"]={"업데이트 후 패치 노트가 자동으로 열리면 이제 컨트롤러 포커스를 받습니다. 뒤로 버튼으로 바로 닫을 수 있습니다.","오른쪽 스틱으로 스크롤할 때 스크롤 막대도 본문과 함께 움직이고, 저장된 읽기 위치도 갱신됩니다.","기록을 탐색하다가 선택한 버튼이 사라지거나 비활성화되면 사용 가능한 항목으로 선택이 이동합니다. 페이지를 바꾼 뒤에도 탐색 대상이 갱신됩니다."},["title"]="패치 노트 컨트롤러 조작 수정"}},["version"]="9.2.0-beta.1",["welcome"]="패치 노트를 컨트롤러로 읽고 닫기 쉽도록 베타 버전을 수정했습니다."},["ptBR"]={["sections"]={{["items"]={"As notas que abrem automaticamente após uma atualização agora recebem o foco do controle. Assim, você pode fechá-las diretamente com Voltar.","A rolagem pelo analógico direito agora move a barra junto com o texto e atualiza a posição de leitura guardada.","A navegação no Histórico passa a seleção para um controle válido quando um botão desaparece ou fica indisponível. Os controles também são atualizados ao trocar de página."},["title"]="Controle nas notas da atualização"}},["version"]="9.2.0-beta.1",["welcome"]="Esta pequena atualização da beta melhora a leitura das notas com controle."},["ruRU"]={["sections"]={{["items"]={"Автоматически открывшиеся заметки теперь получают фокус геймпада. Их можно сразу закрыть кнопкой «Назад».","При прокрутке правым стиком полоса прокрутки теперь движется вместе с текстом, а сохранённая позиция чтения обновляется.","В Истории выбор переносится на доступный элемент, если текущая кнопка скрывается или отключается. После перехода на другую страницу навигация обновляется."},["title"]="Управление окном заметок"}},["version"]="9.2.0-beta.1",["welcome"]="Небольшое обновление бета-версии улучшает работу с заметками к обновлениям на геймпаде."},["zhCN"]={["sections"]={{["items"]={"更新后自动打开的说明窗口现在会获得手柄焦点，可以直接用返回键关闭。","右摇杆滚动正文时，滚动条会同步移动，保存的阅读位置也会随之更新。","浏览历史页面时，如果当前按钮隐藏或不可用，选择焦点会安全地移到可用控件；切换页面后也会刷新导航。"},["title"]="更新说明窗口修复"}},["version"]="9.2.0-beta.1",["welcome"]="本次手柄测试版小更新修复了更新说明窗口的操作问题。"},["zhTW"]={["sections"]={{["items"]={"更新後自動開啟的說明視窗現在會取得控制器焦點，可以直接按返回鍵關閉。","使用右類比搖桿捲動內文時，捲軸也會同步移動，儲存的閱讀位置會一併更新。","瀏覽歷史紀錄時，若選取的按鈕隱藏或停用，焦點會移至可用控制項；換頁後也會更新導覽項目。"},["title"]="更新說明視窗修正"}},["version"]="9.2.0-beta.1",["welcome"]="這次控制器 Beta 版小更新改善了更新說明視窗的閱讀與操作。"}}
